const stylePrompts: Record<StickerStyle, string> = {
  minimalist: 'flat vector graphic, simple shapes, minimalist clean aesthetic',
  'pop-art': 'vibrant pop art, high contrast comic book illustration',
  kawaii: 'cute kawaii character art, soft round proportions, pastel colors',
  'retro-vinyl': 'thick vinyl sticker, 90s retro style, bold clean outlines',
  cyberpunk: 'neon-lit futuristic graphic, cyberpunk tech aesthetic, high contrast',
  holographic: 'prismatic holographic sticker, iridescent rainbow reflections, shiny foil',
  vaporwave: '80s vaporwave aesthetic, pink and teal gradients, retro tech graphic',
  '3d-render': '3D claymation style render, smooth rounded surfaces, studio lighting',
  'ink-sketch': 'hand-drawn ink illustration, textured paper, bold artistic lines',
  'pixel-art': 'retro 8-bit pixel graphics, blocky video game aesthetic',
  watercolor: 'soft watercolor pigments, artistic bleeding edges, delicate texture',
  embroidery: 'textured embroidered patch, visible thread patterns, stitched borders',
  graffiti: 'urban graffiti street art, spray paint textures, vibrant dripping colors',
  origami: 'folded paper origami art, geometric sharp facets, paper texture',
  'clear-vinyl': 'translucent clear vinyl aesthetic, glossy vector subject, clean reflections'
