const shapeOptions: Record<StickerShape, string> = {
  'die-cut': 'Custom Cut',
  circle: 'Circle',
  square: 'Square',
  badge: 'Badge',
  heart: 'Heart',
  hexagon: 'Hexagon'
};

const paletteOptions: Record<StickerPalette, string> = {
  default: 'Original',
  vibrant: 'Vibrant',
  pastel: 'Pastel',
  neon: 'Neon',
  vintage: 'Vintage',
  noir: 'Noir',
  earthy: 'Earthy'
};

const paletteColors: Record<StickerPalette, string[]> = {
  default: ['#969696', '#595959', '#ffffff'],
  vibrant: ['#ff00ff', '#00ffff', '#ffff00'],
  pastel: ['#ffd1dc', '#b2e2f2', '#e2f0cb'],
  neon: ['#39ff14', '#fe019a', '#00ffff'],
  vintage: ['#8b4513', '#d2b48c', '#556b2f'],
  noir: ['#000000', '#333333', '#ffffff'],
  earthy: ['#4b5320', '#6b8e23', '#bc8f8f']
};

const palettePrompts: Record<StickerPalette, string> = {
  default: '',
  vibrant: 'vivid saturated color palette',
  pastel: 'soft desaturated pastel colors',
  neon: 'electric neon glow colors',
  vintage: 'muted vintage retro tones',
  noir: 'black and white monochromatic',
  earthy: 'natural organic earth tones'
};

const modelOptions = [
  '🍌 Nano Banana Pro',
  '🍌 Nano Banana 2',
  '🍌 Nano Banana 2 Lite'
];

const THEME = {
  art: '#2979FF',    
  palette: '#F43F5E', 
  form: '#06B6D4',    
  accent: '#FFD600',  
  action: '#2979FF',  
  generate: '#39FF14' 
};

export default function App() {
  const allStyles = Object.keys(styleOptions) as StickerStyle[];
  const defaultSamplerStyles: StickerStyle[] = ['minimalist', 'pop-art', 'kawaii', 'retro-vinyl'];

  const [state, setState] = useState<StickerState>({
    originalImage: null,
    originalMime: null,
    cutoutImage: null,
    cutoutMediaId: null,
    generatedSticker: null,
    samplerImages: {},
    failedSamplerStyles: [],
    selectedSamplerStyles: defaultSamplerStyles, 
    canvasItems: [],
    viewMode: 'single',
    isLoading: false,
    status: '',
    error: null,
  });

  const [settings, setSettings] = useState<StickerSettings>({
    style: 'minimalist',
    shape: 'die-cut',
    palette: 'default',
    finish: 'glossy',
    borderThickness: 2, 
    backgroundColor: 'white',
    customSubject: '',
    useSmartCutout: true, 
    styleGuidance: '',
    captionText: '',
    model: '🍌 Nano Banana Pro',
  });

  const [downloadState, setDownloadState] = useState<'idle' | 'busy' | 'done' | 'error'>('idle');
  const [sheetDownloadState, setSheetDownloadState] = useState<'idle' | 'busy' | 'done' | 'error'>('idle');
  const [samplerDownloadState, setSamplerDownloadState] = useState<'idle' | 'busy' | 'done' | 'error'>('idle');
  const [canvasExportState, setCanvasExportState] = useState<'idle' | 'busy' | 'done' | 'error'>('idle');

  useEffect(() => {
    const id = 'sticker-studio-standard-css';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }
      .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }
      .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #333 transparent; }
      .dark-scrollbar::-webkit-scrollbar { width: 4px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #333; border-radius: 9999px; }
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #080808; font-family: 'Google Sans Text', sans-serif; color: white; overflow: hidden; }
      .checkerboard { background-image: linear-gradient(45deg, #111 25%, transparent 25%), linear-gradient(-45deg, #111 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #111 75%), linear-gradient(-45deg, transparent 75%, #111 75%); background-size: 20px 20px; background-position: 0 0, 0 10px, 10px -10px, -10px 0px; }
      .drop-shadow-sticker { filter: drop-shadow(0 15px 30px rgba(0,0,0,0.4)); }
    `;
    document.head.appendChild(style);
  }, []);

  const sanitizeFilename = (name: string, style: string): string => {
    return `${name.replace(/[^a-z0-9]/gi, '_') || 'sticker'}_${style}_sticker.png`;
  };

  const getProcessingMediaId = async (): Promise<string> => {
    if (!state.originalImage) throw new Error('No image selected');
    if (state.cutoutMediaId) return state.cutoutMediaId;

    if (!settings.useSmartCutout) {
      const base64 = state.originalImage.split(',')[1];
      const uploaded = await Flow.upload({
        base64,
        mimeType: state.originalMime as any || 'image/png',
        name: 'Sticker Original'
      });
      setState(prev => ({ ...prev, cutoutMediaId: uploaded.mediaId }));
      return uploaded.mediaId;
    }

    let currentCutoutUrl = state.cutoutImage;
    if (!currentCutoutUrl) {
      setState(prev => ({ ...prev, status: 'Isolating Subject...' }));
      currentCutoutUrl = await removeBackground(state.originalImage!, (p) => {
        setState(prev => ({ ...prev, status: `Background Removal: ${Math.round(p)}%` }));
      });
      setState(prev => ({ ...prev, cutoutImage: currentCutoutUrl }));
    }

    setState(prev => ({ ...prev, status: 'Uploading...' }));
    const base64 = currentCutoutUrl.split(',')[1];
    const uploaded = await Flow.upload({
      base64,
      mimeType: 'image/png',
      name: 'Sticker Subject'
    });
    setState(prev => ({ ...prev, cutoutMediaId: uploaded.mediaId }));
    return uploaded.mediaId;
  };

  const buildPrompt = (style: StickerStyle) => {
    const borderStr = settings.borderThickness === 0 ? '' : `${settings.borderThickness === 1 ? 'thin' : 'thick'} clean white border, `;
    const shapeStr = settings.shape === 'die-cut' ? '' : `contained in a ${settings.shape} shape, `;
    const paletteStr = settings.palette === 'default' ? '' : `${palettePrompts[settings.palette]}, `;
    const bgStr = settings.backgroundColor === 'white' ? 'pure white background' : 'solid uniform gray background';
    const subjectDesc = settings.customSubject ? `showing ${settings.customSubject}` : 'preserving the original subject details';
    const guidance = settings.styleGuidance ? `, emphasizing ${settings.styleGuidance}` : '';
    const caption = settings.captionText ? `, featuring the text "${settings.captionText}"` : '';

    return `Professional die-cut sticker ${subjectDesc}${caption}. Style: ${stylePrompts[style]}. Details: ${shapeStr}${borderStr}${settings.finish} finish, ${paletteStr}isolated on a ${bgStr}${guidance}. High quality vector illustration, clean lines, professional digital art.`;
  };

  const generateSticker = async () => {
    if (!state.originalImage) return;
    setState(prev => ({ ...prev, isLoading: true, status: 'Starting AI...', error: null }));

    try {
      const currentMediaId = await getProcessingMediaId();
      const prompt = buildPrompt(settings.style);
      setState(prev => ({ ...prev, status: `Generating Sticker...` }));

      const result = await Flow.generate.image({
        prompt,
        referenceImageMediaIds: [currentMediaId],
        modelDisplayName: settings.model,
        aspectRatio: '1:1'
      });

      setState(prev => ({
        ...prev,
        generatedSticker: `data:${result.mimeType};base64,${result.base64}`,
        isLoading: false,
        status: '',
        viewMode: 'single'
      }));

    } catch (err: any) {
      handleError(err);
    }
  };

  const generateSampler = async () => {
    if (!state.originalImage) return;
    const activeStyles = state.selectedSamplerStyles;
    if (activeStyles.length === 0) return;

    setState(prev => ({ 
      ...prev, 
      isLoading: true, 
      status: 'Queueing Samples...', 
      error: null,
      samplerImages: {},
      failedSamplerStyles: [] 
    }));

    try {
      const currentMediaId = await getProcessingMediaId();

      for (let i = 0; i < activeStyles.length; i++) {
        const style = activeStyles[i];
        setState(prev => ({ ...prev, status: `Style ${i + 1}/${activeStyles.length}...` }));
        const prompt = buildPrompt(style);

        try {
          const result = await Flow.generate.image({
            prompt,
            referenceImageMediaIds: [currentMediaId],
            modelDisplayName: settings.model,
            aspectRatio: '1:1'
          });
          const dataUrl = `data:${result.mimeType};base64,${result.base64}`;
          setState(prev => ({ 
            ...prev, 
            samplerImages: { ...prev.samplerImages, [style]: dataUrl } 
          }));
        } catch (styleErr: any) {
          console.warn(`Style ${style} blocked/failed:`, styleErr);
          setState(prev => ({ 
            ...prev, 
            failedSamplerStyles: [...prev.failedSamplerStyles, style] 
          }));
        }

        if (i < activeStyles.length - 1) {
          await new Promise(r => setTimeout(r, 500));
        }
      }
      setState(prev => ({ ...prev, isLoading: false, status: '', viewMode: 'sampler' }));
    } catch (err: any) {
      handleError(err);
    }
  };

  const handleError = (err: any) => {
    const errorMsg = String(err?.message || err?.code || '');
    let msg = 'AI request failed. Please try again with a different subject.';

    if (errorMsg.includes('UNSAFE')) {
      msg = 'Content Policy: The AI flagged this prompt as unsafe. Try a simpler description or a different subject image.';
    } else if (errorMsg.includes('SOMETHING_WENT_WRONG')) {
      msg = 'Service Timeout: The generation took too long. Try switching to the "Lite" model for faster results.';
    } else if (errorMsg.includes('429')) {
      msg = 'Rate Limit: Too many requests at once. Please wait 10 seconds before trying again.';
    }

    setState(prev => ({ ...prev, isLoading: false, status: '', error: msg }));
  };

  const addToCanvas = () => {
    if (!state.generatedSticker) return;
    const newItem: CanvasItem = {
      id: Math.random().toString(36).substr(2, 9),
      url: state.generatedSticker,
      x: 100 + Math.random() * 200,
      y: 100 + Math.random() * 200,
      rotation: 0,
      scale: 1
    };
    setState(prev => ({ 
      ...prev, 
      canvasItems: [...prev.canvasItems, newItem],
      viewMode: 'canvas' 
    }));
  };

  const handleDownloadSingle = async () => {
    if (!state.generatedSticker) return;
    setDownloadState('busy');
    try {
      await Flow.download({
        base64: state.generatedSticker.split(',')[1],
        mimeType: 'image/png',
        filename: sanitizeFilename(settings.customSubject || 'sticker', settings.style)
      });
      setDownloadState('done');
      setTimeout(() => setDownloadState('idle'), 2000);
    } catch {
      setDownloadState('error');
      setTimeout(() => setDownloadState('idle'), 3000);
    }
  };

  const handleDownloadSheet = async () => {
    if (!state.generatedSticker) return;
    setSheetDownloadState('busy');
    try {
      const canvas = document.createElement('canvas');
      canvas.width = 1500;
      canvas.height = 1500;
      const ctx = canvas.getContext('2d')!;

      ctx.fillStyle = 'white';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      const img = new Image();
      img.crossOrigin = 'anonymous';
      await new Promise((resolve, reject) => {
        img.onload = resolve;
        img.onerror = reject;
        img.src = state.generatedSticker!;
      });

      const spacing = 500;
      for (let y = 0; y < 3; y++) {
        for (let x = 0; x < 3; x++) {
          ctx.save();
          ctx.translate(x * spacing + 250, y * spacing + 250);
          ctx.drawImage(img, -200, -200, 400, 400);
          ctx.restore();
        }
      }

      const base64 = canvas.toDataURL('image/png').split(',')[1];
      await Flow.download({
        base64,
        mimeType: 'image/png',
        filename: `sticker_sheet_${settings.style}.png`
      });
      setSheetDownloadState('done');
      setTimeout(() => setSheetDownloadState('idle'), 2000);
    } catch {
      setSheetDownloadState('error');
      setTimeout(() => setSheetDownloadState('idle'), 3000);
    }
  };

  const handleDownloadSamplerSheet = async () => {
    const styleKeys = Object.keys(state.samplerImages) as StickerStyle[];
    if (styleKeys.length === 0) return;

    setSamplerDownloadState('busy');
    try {
      const canvas = document.createElement('canvas');
      const cols = 3;
      const rows = Math.ceil(styleKeys.length / cols);
      const cellSize = 500;

      canvas.width = cols * cellSize;
      canvas.height = rows * cellSize;
      const ctx = canvas.getContext('2d')!;

      ctx.fillStyle = 'white';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      for (let i = 0; i < styleKeys.length; i++) {
        const style = styleKeys[i];
        const url = state.samplerImages[style]!;
        const img = new Image();
        img.crossOrigin = 'anonymous';
        await new Promise((resolve, reject) => {
          img.onload = resolve;
          img.onerror = reject;
          img.src = url;
        });

        const x = (i % cols) * cellSize;
        const y = Math.floor(i / cols) * cellSize;

        ctx.drawImage(img, x + 50, y + 50, 400, 400);

        // Label
        ctx.fillStyle = '#000';
        ctx.font = 'bold 24px Google Sans Text';
        ctx.textAlign = 'center';
        ctx.fillText(styleOptions[style].toUpperCase(), x + 250, y + 470);
      }

      const base64 = canvas.toDataURL('image/png').split(',')[1];
      await Flow.download({
        base64,
        mimeType: 'image/png',
        filename: `sampler_sheet_${settings.customSubject || 'stickers'}.png`
      });
      setSamplerDownloadState('done');
      setTimeout(() => setSamplerDownloadState('idle'), 2000);
    } catch {
      setSamplerDownloadState('error');
      setTimeout(() => setSamplerDownloadState('idle'), 3000);
    }
  };

