                  onUpdateItems={(items) => setState(s => ({ ...s, canvasItems: items }))}
                  onExport={handleExportCanvas}
                  exportState={canvasExportState}
                />
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useRef } from 'react';
import { motion } from 'motion/react';
import { CanvasItem } from '../types';
import { PillButton } from './Primitives';

interface CanvasEditorProps {
  items: CanvasItem[];
  onUpdateItems: (items: CanvasItem[]) => void;
  onExport: () => void;
  exportState: 'idle' | 'busy' | 'done' | 'error';
}

export const CanvasEditor: React.FC<CanvasEditorProps> = ({ 
  items, 
  onUpdateItems, 
  onExport,
  exportState 
}) => {
  const [canvasBg, setCanvasBg] = useState<'dark' | 'light' | 'checker'>('checker');
  const containerRef = useRef<HTMLDivElement>(null);

  const updateItem = (id: string, delta: Partial<CanvasItem>) => {
    onUpdateItems(items.map(item => item.id === id ? { ...item, ...delta } : item));
  };

  const removeItem = (id: string) => {
    onUpdateItems(items.filter(item => item.id !== id));
  };

  const bringToFront = (id: string) => {
    const item = items.find(i => i.id === id);
    if (!item) return;
    onUpdateItems([...items.filter(i => i.id !== id), item]);
  };

  return (
    <div className="flex flex-col items-center gap-6 w-full h-full p-4">
      <div className="flex items-center justify-between w-full max-w-4xl px-4">
        <div className="flex items-center gap-4">
          <div className="flex bg-white/5 p-1 rounded-xl border border-white/10">
            {(['checker', 'dark', 'light'] as const).map(bg => (
              <button
                key={bg}
                type="button"
                onClick={() => setCanvasBg(bg)}
                className={`px-3 py-1.5 rounded-lg text-[12px] font-bold uppercase tracking-widest transition-all ${
                  canvasBg === bg ? 'bg-white/10 text-white' : 'text-white/40 hover:text-white/60'
                }`}
              >
                {bg}
              </button>
            ))}
          </div>
        </div>

        <div className="flex gap-2">
           <PillButton 
            variant="outline" 
            icon={<span className="material-symbols-outlined text-[18px]">delete</span>} 
            onClick={() => onUpdateItems([])}
            className="w-auto px-4"
          >
            Clear
          </PillButton>
          <PillButton 
            variant="solid" 
            icon={<span className="material-symbols-outlined text-[18px]">download</span>} 
            onClick={onExport}
            disabled={exportState !== 'idle' || items.length === 0}
            className="w-auto px-6"
          >
            {exportState === 'busy' ? '...' : exportState === 'done' ? '✓' : 'Export'}
          </PillButton>
        </div>
      </div>

      <div 
        ref={containerRef}
        className={`relative flex-1 w-full max-w-4xl aspect-square rounded-[40px] overflow-hidden border border-white/10 shadow-2xl transition-all duration-500 ${
          canvasBg === 'checker' ? 'checkerboard' : canvasBg === 'dark' ? 'bg-[#1a1a1a]' : 'bg-white'
        }`}
      >
        {items.length === 0 ? (
          <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 text-white/10">
            <span className="material-symbols-outlined text-[100px]">layers</span>
            <p className="uppercase font-black tracking-[8px]">Canvas Empty</p>
            <p className="text-[12px] uppercase tracking-[2px] opacity-40">Add stickers from the Single view</p>
          </div>
        ) : (
          items.map((item) => (
            <motion.div
              key={item.id}
              drag
              dragMomentum={false}
              dragConstraints={containerRef}
              onDragStart={() => bringToFront(item.id)}
              style={{ x: item.x, y: item.y, rotate: item.rotation, scale: item.scale }}
              onDragEnd={(e, info) => {
                updateItem(item.id, { 
                  x: item.x + info.offset.x, 
                  y: item.y + info.offset.y 
                });
              }}
              className="absolute cursor-grab active:cursor-grabbing group p-0"
              style={{ width: 200, height: 200 }}
            >
              <div className="relative w-full h-full">
                <img 
                  src={item.url} 
                  className="w-full h-full object-contain drop-shadow-sticker select-none pointer-events-none" 
                  alt="Canvas Sticker" 
                />

                {/* Controls overlay */}
                <div className="absolute -top-4 -right-4 flex flex-col gap-2 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                  <button 
                    type="button"
                    onClick={(e) => { e.stopPropagation(); removeItem(item.id); }}
                    className="w-8 h-8 rounded-full bg-red-500 text-white flex items-center justify-center shadow-lg hover:scale-110 active:scale-90 transition-transform"
                  >
                    <span className="material-symbols-outlined text-[18px]">close</span>
                  </button>
                  <button 
                    type="button"
                    onClick={(e) => { e.stopPropagation(); updateItem(item.id, { rotation: item.rotation + 15 }); }}
                    className="w-8 h-8 rounded-full bg-white text-black flex items-center justify-center shadow-lg hover:scale-110 active:scale-90 transition-transform"
                  >
                    <span className="material-symbols-outlined text-[18px]">rotate_right</span>
                  </button>
                  <button 
                    type="button"
                    onClick={(e) => { e.stopPropagation(); updateItem(item.id, { scale: Math.min(2, item.scale + 0.1) }); }}
                    className="w-8 h-8 rounded-full bg-white text-black flex items-center justify-center shadow-lg hover:scale-110 active:scale-90 transition-transform"
                  >
                    <span className="material-symbols-outlined text-[18px]">zoom_in</span>
                  </button>
                  <button 
                    type="button"
                    onClick={(e) => { e.stopPropagation(); updateItem(item.id, { scale: Math.max(0.5, item.scale - 0.1) }); }}
                    className="w-8 h-8 rounded-full bg-white text-black flex items-center justify-center shadow-lg hover:scale-110 active:scale-90 transition-transform"
                  >
                    <span className="material-symbols-outlined text-[18px]">zoom_out</span>
                  </button>
                </div>
              </div>
            </motion.div>
          ))
        )}
      </div>
    </div>
  );
};
